// Let's create a temporary canvas in the page (or a helper) to inspect the screenshot image pixels!
const tabId = 825319264;
const snap = await browser.screenshot({ tabId });
console.log("Screenshot URI:", snap.image.uri);

const coords = await browserjs(tabId, async (uri) => {
  // Let's draw the image to an offscreen canvas to find where the black border of the PRESS & HOLD button is
  const img = new Image();
  img.src = uri;
  await new Promise(r => img.onload = r);
  const canvas = document.createElement('canvas');
  canvas.width = img.width;
  canvas.height = img.height;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, 0, 0);
  const data = ctx.getImageData(0, 0, img.width, img.height).data;

  // Look for the black pill button around x = 400..800, y = 350..650
  // The border is dark (near black, r,g,b < 50)
  const hits = [];
  for (let y = 350; y < img.height; y++) {
    for (let x = 400; x < 880; x++) {
      const idx = (y * img.width + x) * 4;
      const r = data[idx], g = data[idx+1], b = data[idx+2];
      if (r < 60 && g < 60 && b < 60) {
        hits.push({ x, y });
      }
    }
  }
  if (!hits.length) return { error: "no dark pixels found" };
  const minX = Math.min(...hits.map(h => h.x));
  const maxX = Math.max(...hits.map(h => h.x));
  const minY = Math.min(...hits.map(h => h.y));
  const maxY = Math.max(...hits.map(h => h.y));
  return { minX, maxX, minY, maxY, centerX: (minX + maxX)/2, centerY: (minY + maxY)/2, count: hits.length };
}, snap.image.uri);

console.log("Coords:", coords);

