const tabId = 825319331;
const apiRes = await browserjs(tabId, async () => {
  const url = "https://www.ryanair.com/api/booking/v4/en-gb/availability?ADT=1&CHD=0&DateIn=2026-11-28&DateOut=2026-11-18&Destination=BUD&Disc=0&INF=0&Origin=STN&TEEN=0&daysIn=6&daysOut=6&includeConnectingFlights=false&roundtrip=true";
  const r = await fetch(url);
  const data = await r.json();
  return {
    status: r.status,
    currency: data.currency,
    trips: data.trips?.map(t => ({
      origin: t.originName,
      destination: t.destinationName,
      dates: t.dates?.map(d => ({
        dateOut: d.dateOut,
        flights: d.flights?.map(f => ({
          flightNumber: f.flightNumber,
          time: f.time,
          fare: f.regularFare?.fares?.[0]?.amount
        }))
      }))
    }))
  };
});
console.log("Ryanair Availability API result:", JSON.stringify(apiRes, null, 2));

