const tabId = 825319332;
const reviewInfo = await browserjs(tabId, () => {
  // Let's get overall score, descriptor, count, and review cards
  const scoreBadge = document.querySelector('[data-testid="review-score-right-component"]') || document.querySelector('[data-testid="review-score"]');
  const reviewScore = scoreBadge?.textContent?.trim();

  // Find review container or button to open reviews
  const reviewButton = Array.from(document.querySelectorAll('button, a')).find(el => el.textContent && el.textContent.includes('reviews') && /\d+/.test(el.textContent));

  // Let's look for review items on page
  const reviewElements = Array.from(document.querySelectorAll('[data-testid="review-card"], [itemprop="review"], .review_item'));
  const reviews = reviewElements.map(r => r.textContent.trim());

  return {
    title: document.querySelector('#hp_hotel_name, [data-testid="header-title"]')?.textContent?.trim(),
    reviewScore,
    reviewButtonText: reviewButton?.textContent?.trim(),
    reviewsCount: reviews.length,
    reviewsSnippet: reviews.slice(0, 5)
  };
});
console.log("Review info:", JSON.stringify(reviewInfo, null, 2));

