  console.log("Sample reviews:", JSON.stringify(reviews.slice(0, 5), null, 2));
} else {
  // Let's check page HTML or modal text
  const modal = document.querySelector('[role="dialog"], [data-testid="modal-container"]');
  console.log("Modal present?", !!modal, modal?.textContent?.slice(0, 500));
}

