const tabId = 825319333;
const reviewInfo = await browserjs(tabId, () => {
  const scoreBadge = document.querySelector('[data-testid="review-score-right-component"]') || document.querySelector('[data-testid="review-score"]');
  const reviewScore = scoreBadge?.textContent?.trim();

  const title = document.querySelector('#hp_hotel_name, [data-testid="header-title"]')?.textContent?.trim();

  const reviewButton = Array.from(document.querySelectorAll('button, a')).find(el => el.textContent && el.textContent.includes('reviews') && /\d+/.test(el.textContent));

  return {
    title,
    reviewScore,
    reviewButtonText: reviewButton?.textContent?.trim()
  };
});
console.log("Review info for Chapter Hotels:", JSON.stringify(reviewInfo, null, 2));

// Click review button to open reviews
const clickRes = await browserjs(tabId, () => {
  const btn = Array.from(document.querySelectorAll('button, a')).find(el => el.textContent && el.textContent.includes('reviews') && /\d+/.test(el.textContent));
  if (btn) {
    btn.click();
    return "clicked review button";
  }
  return "not found";
});
console.log("Click result:", clickRes);
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2000 });

const reviews = await browserjs(tabId, () => {
  const reviewCards = Array.from(document.querySelectorAll('[data-testid="review-card"], [itemprop="review"], [data-review-id], .c-review-block, .review_item, [data-testid="featured-review"]'));
  return reviewCards.map(rc => rc.textContent.trim().replace(/\s+/g, ' '));
});
console.log("Reviews count:", reviews.length);
console.log("Recent reviews:", JSON.stringify(reviews.slice(0, 8), null, 2));

